import{_ as p,a as o,b as r,c as s,d as n}from"./chunks/2ecceeb054b15c810548.DgJWABfU.js";import{_ as l,C as i,o as m,c,j as t,a as g,E as h,a5 as u}from"./chunks/framework.DNkHA0lr.js";const T=JSON.parse('{"title":"HUMAN 3.0 —— 通往顶尖 1% 的地图","description":"","frontmatter":{"title":"HUMAN 3.0 —— 通往顶尖 1% 的地图","originalTitle":"HUMAN 3.0 – A Map To Reach The Top 1%","date":"2025-08-26","originalUrl":"https://thedankoe.com/letters/human-3-0-a-map-to-reach-the-top-1/","minutes":19,"sourceHash":"e8b2441ae8acad6ec2ba005cfa466d1840339687e68f96593d2c124bb49abb8b","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/human-3-0-a-map-to-reach-the-top-1/"}]]},"headers":[],"relativePath":"letters/human-3-0-a-map-to-reach-the-top-1.md","filePath":"letters/human-3-0-a-map-to-reach-the-top-1.md"}'),d={name:"letters/human-3-0-a-map-to-reach-the-top-1.md"};function b(_,e,f,k,A,q){const a=i("ArticleMeta");return m(),c("div",null,[e[0]||(e[0]=t("h1",{id:"human-3-0-——-通往顶尖-1-的地图",tabindex:"-1"},[g("HUMAN 3.0 —— 通往顶尖 1% 的地图 "),t("a",{class:"header-anchor",href:"#human-3-0-——-通往顶尖-1-的地图","aria-label":'Permalink to "HUMAN 3.0 —— 通往顶尖 1% 的地图"'},"​")],-1)),h(a),e[1]||(e[1]=u('<p>尽管听起来可能有些俗气，但我一直想成为一股不容小觑的力量。</p><p>一个极其强悍的个体。</p><p>不仅仅是拥有一副好看健硕的皮囊，而是在生活的每个领域都得到充分的发展。</p><p>我想要变得多维度的强悍。我想把所有的属性点拉满。我不想当个 NPC。我想成为一个 100 级玩家。解锁地图的所有区域。体能、智力和职业技能全部升到满级。银行里金币溢出。我想拥有一切。头脑、身体、精神、人际关系、金钱。</p><p>这种渴望极大地影响了我的生活。</p><p>十多岁的时候，我沉迷于健身。后来，我想尽可能多地吸收知识。再后来，我渴望自由，因此在各种商业模式上栽了跟头，直到最终摸索出一条可行的路。我也有过几段精神和哲学上的探索经历，我相信这些经历帮助我以一种与常人截然不同的视角，来看待金钱和健身这类“肤浅的追求”。</p><p>在过去的 15 年里，我深入研究了心理学、个人发展、哲学、社会动力学、技术、互联网、初创企业、金钱、宗教和意义的深层领域。</p><p>在过去 5 年里，我一直在网上撰写我的发现，之后我注意到了一些关键的重叠模式，它们已经开始为当今世界构建出一种全新的哲学。</p><p>这就是 HUMAN 3.0（人类 3.0）的由来。</p><p>我想把我学到的一切综合成一张全面的地图，以指引你在现代社会的版图中航行。我想为你提供知识、技能和原则，帮助你摆脱平庸，实现你的最高潜能。我会尽量让这些内容有科学依据且不教条，但我也想 <em>清晰且坚定地把观点传达出来</em>。我打算用清晰、自然的语言为当今世界写下这些文字，同时尽可能地简化这些概念，以免它变成一本无人问津的教科书。因此，我将用我一贯的口吻来表达，把细微的差别交给你去体会。因为细微的差别和批判性思维总是掌握在读者手中的。</p><p>这将是一个持续连载的系列，我们将在这里剖析人类的体验，重写你的现实，从而让你过上最美好的生活。</p><p>其中很多内容可能会是错的，我鼓励你质疑我的话。事实上，我希望你能和我一起把它构建出来。如果你在自己的写作或内容中谈论 HUMAN 3.0，我会很高兴看到。拿走这些想法，并在它们的基础上继续构建。如果你喜欢 H3.0 模型，那就用它。</p><p>现在，市面上已经有很多不可思议的模型和“大师”了。</p><p>螺旋动力学（心理学）、佛教与基督教（意义）、唯物主义与唯心主义（现实的本质）、电子商务与咨询（商业）、红药丸与女权主义（社会动力学）等等。无论你看向哪里，你都能找到数百种模型，承诺为你解决所有问题。</p><p>它们都有自己的道理，但致命的缺陷在于，它们都局限于生活的一个领域。我们把数学、英语和科学当作单一、孤立的课程来学，而知识其实是一张网。我们在实验室里解剖青蛙并得出结论，却不考虑青蛙所处的整个生态系统和相互联系的关系。除此之外，尽管对某些人来说很难接受，许多精神导师的身体都很虚弱；许多商人无法维持人际关系；许多“阿尔法男（alpha males）”情绪严重失调。虽然他们在各自的领域都取得了了不起的成就，但很少有人能在真正意义上实现全面的自我发展。</p><p>即使这些模型或大师确实连接了多个领域（比如古希腊哲学），它们也通常是在互联网、科技和人工智能开始改变一切之前就已经盛行的。更重要的一点是，很少有人触及工作和金钱等领域，这令人惊讶，因为这些东西占据了大多数人的头脑和生活。</p><p>今天，我们将奠定 HUMAN 3.0 的基础。</p><p>在接下来的几个月（也许几年）里，我们将揭开把生活发挥到极致的真正含义。在这篇介绍中，我无法涵盖这个模型所包含的所有细节。</p><h2 id="human-3-0-——-一个最大化你潜能的模型" tabindex="-1">HUMAN 3.0 —— 一个最大化你潜能的模型 <a class="header-anchor" href="#human-3-0-——-一个最大化你潜能的模型" aria-label="Permalink to &quot;HUMAN 3.0 —— 一个最大化你潜能的模型&quot;">​</a></h2><p><a href="https://substackcdn.com/image/fetch/$s_!JWUy!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2Fc875a11c-dd46-48ad-b6ab-acef3b576d0e_1277x1000.png" target="_blank" rel="noreferrer"><img src="'+p+'" alt=""></a></p><p>这个模型提供了 <em>宏观的视角</em>。它不是一套教条的可执行步骤，而是一组指导原则，旨在帮助你实现最大潜能，并更快地突破精神、身体、心灵和职业上的瓶颈。它梳理了跨越人类发展过程中的模式，并建立在各种科学、心理学、灵性学和职业学模型的基础之上，这些模型已经完成了大量的基础工作。</p><p>我的目标是汲取世界上最伟大理论的精华，并 <em>将它们应用于个人的生活之中。</em></p><blockquote><p>一旦你理解了这套模型，你就可以开始在每个象限中定位你当前的发展水平（你的“原型”），以及你的整体发展面貌（你的“元类型”）。然后，你可以尝试向 3.0+ 级别的元类型迈进 —— 成为一个将生活各个领域都最大化的人。</p></blockquote><p>我们将在这封信的后半部分讨论这些内容，但现在，让我们先了解一下基础。</p><h3 id="_1-象限" tabindex="-1"><strong>1) 象限</strong> <a class="header-anchor" href="#_1-象限" aria-label="Permalink to &quot;**1) 象限**&quot;">​</a></h3><p>Human 3.0 的基础是代表生活四个领域的四个象限。</p><ul><li><strong>头脑</strong>（个人精神世界）——你的思想、情绪、信仰和内在世界。你如何解读这个世界。</li><li><strong>身体</strong>（个人物理世界）——你的行为和外在仪态。世界如何解读你。包括营养、训练、爱好、习惯、仪容、沟通、穿着等。</li><li><strong>精神</strong>（集体精神世界）——你与环境、社区、文化、家人、朋友、同事以及现实的关系。你如何获取意义和建立连接。</li><li><strong>职业</strong>（集体物理世界）——你与系统、结构和教育、事业、经济等社会制度的关系。你如何融入社会并做出贡献。</li></ul><p>这些象限改编自肯·威尔伯（Ken Wilber）的 AQAL 模型，代表了四个基本的 <em>视角</em>，从而创建了一张涵盖所有知识和经验的通用地图。</p><blockquote><p>这张现实地图可以防止片面的思考，不会将问题简化为单一视角。内在的精神问题，也许不能通过找份新工作等职业手段得到最佳解决。灵性上的问题，也许不能通过营养等身体手段得到最佳解决。一个资本家和一个基督徒在各自的领域都发展得很好，但当他们试图将自己的模型应用到其他领域的问题时，就会经历不必要的痛苦。金钱通常不能解决意义的问题，反之亦然，但这并不意味着它们之间没有密切的联系。所有这些领域都是重叠的，通过在上述所有领域发展自己，你将开始过上一种掌控自己未来的生活。</p><p>既然生命、发展和进化的总体趋势是向着更多的混乱或复杂性展开，而有序的结构被创造出来正是为了容纳这种混乱，我们可以把生命的过程，特别是你的个人生活，称为<strong>“解决问题（problem solving）”。</strong></p></blockquote><p>一粒种子发芽伸展，直到开出一朵花。花比种子要复杂许多倍，为了达到那种状态，它需要从环境中汲取资源来进行自我发展。种子有 <em>生长</em> 的自然欲望，经历了漫长的进化过程，它解决了一个个导致许多其他植物物种灭绝的问题。</p><p>人们可能不认为种子是在有意识地尝试生长或解决问题。尽管如此，通过观察并将这些模式与我们的个人生活联系起来，既然我们创造了语言，这就是 <em>我们</em> 会用的称呼。<strong>我们可以开始理解，生命的自然流动是朝着更高的复杂性发展的。</strong> 复杂性会带来问题，而为了限制由复杂性引发的熵，必须通过创造来产生有序的结构。</p><p>在你个人的进化过程中，你渴望发挥你的潜能 → 你迈入未知领域并开始接触复杂性 → 你获得知识和技能，来解决阻碍你前进的问题（否则就会停滞不前，让混乱吞噬你） → 你的身份感随之扩展，并跃升到一个新的层级 → 这个过程不断重复，除非你陷入了停滞。</p><p>在现实的各个层面和领域都能注意到这种模式。我鼓励你去思考更多的例子，但为了简明起见，我们继续往下讲。</p><h3 id="_2-层次" tabindex="-1"><strong>2) 层次</strong> <a class="header-anchor" href="#_2-层次" aria-label="Permalink to &quot;**2) 层次**&quot;">​</a></h3><p>在每个象限中，有 3 个宏观的发展层次，分别代表低阶意识（1.0）、中阶意识（2.0）和高阶意识（3.0）。</p><p>这些层次改编自发展心理学中的各种模型，如螺旋动力学（Spiral Dynamics）和自我发展的 9 个阶段（9 Stages of Ego Development），它们是对许多心理学理论经过充分研究的叠加整合。简而言之，这些研究表明，我们的头脑（影响我们思考和做决定的价值观、信仰和世界观）随着时间的推移，会经历可预测的演变阶段。</p><ul><li><strong>人类 1.0</strong>（顺从者）——重视既定的权威和传统。其特点是目光短浅、非黑即白的思维模式，并相信世界上只有“唯一正确的方法”，这通常源于童年的条件反射式的教育。</li><li><strong>人类 2.0</strong>（个人主义者）——拒绝规范并追求自己的目标。渴望获得地位，被视为有价值的人。他们不那么目光短浅了，但现在他们相信 <em>他们的</em> 方法才是唯一正确的方法。</li><li><strong>人类 3.0</strong>（综合者）——能够采用多重视角，连接现实的各种模式，并规划新的路径。他们明白所有的视角都蕴含着真理，可以将其综合起来以获得更全面、更互利的结果。他们可能会表现出一些被认为是 1 级特征的行为，比如偏狭，但这只是他们为了屏蔽噪音而做出的刻意选择。</li></ul><p>在诸如螺旋动力学之类的模型中，“螺旋”描述了个体在整个发展过程中，如何将焦点在自我和他人之间切换（比如拒绝宗教社群，拥抱个人的无神论）。在 Human 3.0 中，当一个人在特定象限达到新层次时就会发生这种情况。一个人可能在“头脑”象限成为了个人主义者，这可能会导致他的焦点向“精神”象限转移，而在精神层面上，他们仍处于顺从者阶段，依然屈服于权威。</p><p>每个层次的描述在各个象限中会呈现出不同的形式，比如，一个在“职业”象限（右下角）的 3.0 综合者，可以有效地将 AI 作为杠杆来追求他们的毕生事业；而一个 1.0 顺从者，则由于缺乏知识、技能和经验，会坚信 AI 纯粹是邪恶的。</p><p>在身体象限（右上角），一个低意识的个体对摄入身体的营养毫无了解，从而导致肥胖和懒惰，因为他们没有获得做出更好决定的特质（Traits），而一个高意识的个体了解各种营养素如何与身体相互作用，并且能够调整饮食来服务于他们的目标。</p><blockquote><p>这些层级反映了你在任何特定领域中的自我复杂性。整个“人类 3.0”（Human 3.0）图表代表着<em>你</em>。你越复杂（通过培养视角和扩展意识），生活就会变得越有趣，因为你可以<em>选择</em>你想要接受的挑战。就像电子游戏一样：<strong>层级 1 类似于按脚本运行的 NPC 或非玩家角色，层级 2 是选择自己故事情节的主角，而层级 3 则是能够创造让其他人也喜欢玩的新游戏的程序员。</strong></p><p><strong>注意</strong>：较低或较高的层级并没有“好”或“坏”之分，它们只是某人个人旅程中的不同节点。一个“高意识”的人并不意味着更好，只是更加发展成熟，而这种发展有着显而易见的好处。</p><p>你不会<em>离开</em>任何特定的层级。你超越并包容了前一个层级。你获得了一种更广阔的<em>视角</em>，这让你能够将你在较低阶段获得的知识、技能和工具作为杠杆（leverage）来利用。</p></blockquote><p>我们将在下面深入讨论更多例子。</p><p>订阅以进一步探索“人类 3.0”。</p><h3 id="_3-阶段" tabindex="-1"><strong>3) 阶段</strong> <a class="header-anchor" href="#_3-阶段" aria-label="Permalink to &quot;**3) 阶段**&quot;">​</a></h3><p><a href="https://substackcdn.com/image/fetch/$s_!wUFv!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F72814ebc-318b-4304-a6e3-51828c962056_1277x1000.png" target="_blank" rel="noreferrer"><img src="'+o+'" alt=""></a></p><p>在每个层级内，一个人必须经历3个发展阶段才能达到下一个层级。阶段代表着垂直发展，即向上晋升一个层级或向后倒退。</p><p>当一个人经历深刻的改变时，我们可以观察到3种普遍模式：</p><ul><li><strong>失调（Dissonance）</strong>（阶段 1）—— 一旦一个人“尝够了”当前人生阶段的滋味，并且如果他们没有被狭隘的思想和安逸所麻木，他们就会对自己所处的位置感到厌倦，但不确定接下来会是怎样的人生。</li><li><strong>不确定（Uncertainty）</strong>（阶段 2）—— 如果这个人对自己的厌恶有了充分的察觉，他们就会向未知迈出不确定的一步，并向新知识和新技能敞开大门。</li><li><strong>发现（Discovery）</strong>（阶段 3）—— 就像看地图导航一样，他们发现了教育、工具、资源和洞察力，这些让他们能够达到下一个发展<em>层级</em>。</li></ul><p>为了术语上的方便，我们可以通过将某人所在的阶段附加到其在特定领域内的层级上，来映射其生活中的特定区域。</p><p>举个例子，“天职 2.1”（Vocation 2.1，层级 2，阶段 1）将代表集体外部意识（与系统、结构和社会制度的关系）的发展。“2”代表个人主义者（Individualist）层级，而“.1”代表他们几乎耗尽了那个阶段，必须向层级 3 迈出不确定的一步，去发现下一章有什么。对于天职（Vocation）象限来说，这可能意味着他们追求了一份新职业，但意识到自己爬错了梯子，需要做出转变去发现自己的使命。</p><blockquote><p>在这个过程中，个体很容易经历<strong>虚假蜕变（False Transformation）</strong>。他们可能会觉得仿佛自己已经穿过每个阶段达到了一个新的层级，但他们只是在<em>模仿</em>那个发展层级看起来的样子，而没有进行必需的特质（trait）发展。这是一种自欺欺人，会将人们困在当前的阶段，阻碍他们进一步前进，直到他们解决掉当前层级遗留的问题。</p><p>这种虚假蜕变可能会在一个人在一个领域（比如心灵领域）发展了自己，并假设自己也在另一个领域（比如精神或天职领域）取得了进步时发生。</p><p>个体在经历短暂的压力时期，或者当当前层级之外的问题进入他们的生活时，也有可能<strong>倒退</strong>到更低的层级。这就解释了为什么你可能会回首某个“感觉一切都更好”的时期，并渴望把那种感觉带回当下。</p></blockquote><p>正如心流（flow）心理学和尼采（Nietzsche）等许多哲学家的沉思所表明的那样，令人愉快的生活在于通过克服阻力在这些阶段中不断前进。深刻的改变很少是偶然发生的。当你有意图地对待你的愿景、目标和优先事项，而不因为分心和安逸而倒退时，那些在这些阶段会吞噬大多数人的混乱，就会变得可以忍受，并且通常会成为生活中你最为珍视的、最充实的部分。</p><p>在层级 3 及更高层次，个体可以追求更复杂的挑战，并出于对这场游戏的热爱来<em>模拟</em>这些阶段（就像一位 CEO 卖掉了自己的公司，变得抑郁，然后从一个更开悟的视角重新创办一家公司），而且由于游戏是他们创造的，它便成了一场无限游戏。</p><h3 id="_4-特质" tabindex="-1"><strong>4) 特质</strong> <a class="header-anchor" href="#_4-特质" aria-label="Permalink to &quot;**4) 特质**&quot;">​</a></h3><p><a href="https://substackcdn.com/image/fetch/$s_!kB4q!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2Fd85e54d0-f6a2-43a4-9742-0b2d4f386a3a_1277x1000.png" target="_blank" rel="noreferrer"><img src="'+r+'" alt=""></a></p><p>在每个阶段内，都有一个知识、经验和技能的阈值，你必须获取这些，下一个层级才会向你显现。虽然阶段代表着<em>垂直</em>发展，但特质代表着<em>水平</em>发展，或者说在未知中探索，直到你发现了足够多的东西来达到下一个阶段。</p><p>每个象限、层级和阶段都会提出不同的挑战，这些挑战需要一定水平的技能。这种技能需要通过实验和教育来获得。</p><blockquote><p>一个人可以在健身上学识渊博，但如果没有实践和经验，他们就会成为那种肥胖私人教练的原型。他们的知识令人钦佩，但很少有人会当真，这有利也有弊。</p></blockquote><p>无论是垂直（阶段）发展还是水平（特质）发展，陷阱都在于无聊和焦虑。如果你在缺乏相应技能和经验的情况下试图跳跃到新的发展层级，你就会变得焦虑并遭遇失败。如果你根本不尝试向上晋升一个层级，你就会感到无聊，并沉溺于安逸和分心。</p><p>无聊和焦虑都会导致心灵的混乱，让你脱离正在展开的进化洪流。你的生活看起来可能还过得去，但一切都感觉平淡且毫无意义。</p><p>这就引出了通道（Channels）—— 一种对抗混乱并取得实质性进展的方法。</p><h3 id="_5-通道" tabindex="-1">5) 通道 <a class="header-anchor" href="#_5-通道" aria-label="Permalink to &quot;5) 通道&quot;">​</a></h3><p><a href="https://substackcdn.com/image/fetch/$s_!haig!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2Fc1be59ae-04ae-45c7-bf71-9cd9f1d592ba_1277x1000.png" target="_blank" rel="noreferrer"><img src="'+s+'" alt=""></a></p><p>当你到达任何层级的失调（Dissonance）阶段时，你就获得了运用一条“通道”作为杠杆的能力。</p><p>把通道想象成电子游戏里激动人心的任务。一个知识或技能的兔子洞。当你停不下来地研究一个话题或投入一个项目，而时间过得惊人地快时。</p><p>在“人类 3.0”图表上，你可以看到通道的一端位于<em>知识</em>特质中，而另一端位于<em>技能</em>特质中。通常，一个人会“痴迷”于学习或构建，这就导致了经验的快速积累，推动他们迅速朝着特定象限内的下一个发展层级迈进。</p><p>几个例子如下：</p><ul><li><strong>心灵</strong> —— 沉浸在深度冥想状态（技能）中，或者顺着一条让你彻夜难眠的思路，产生出大量点亮你大脑的想法（知识）。</li><li><strong>身体</strong> —— 你发现了一种新的饮食法、补剂或方法论，并疯狂刷完你能找到的所有相关内容（知识）。你痴迷于连续3个月的跑步或举铁，取得了前所未有的进步（技能）。</li><li><strong>精神</strong> —— 神秘体验。蜜月期。亲密时刻。找到了一种与你当前人生阶段“一拍即合”的哲学。等等。</li><li><strong>天职</strong> —— 达到了一种极致清晰的状态，迅速促成了一次激动人心的职业转变、产品发布或创意期（技能）。你找到了完美的机会，停不下来地学习创业所需的技能（知识）。</li></ul><p>进入通道的过程如下。</p><p>首先，在完全适应你所处的层级之后，你必须达到失调（Dissonance）阶段。一旦你对自己所处的境地感到厌倦，如果你没有对自己的问题变得麻木，你就可以把你的厌恶作为燃料，推进到未知领域。你在特定象限（比如身体）内创造一个<em>目标</em>、愿景或目的。你开始获取知识和技能。你边学边做。你犯下错误并完善你的目标。你进行充分的<em>实验</em>，直到你找到那条让你深陷其中的通道。</p><p>你可以通过一个人谈论它时有多<em>兴奋</em>，来判断他是否处于通道之中，就像一个写书写到了文思如泉涌地步的人。他们有愿景。他们的技能和知识提供了一种清晰感，让他们能够在进步中突飞猛进。</p><p>当你处于失调阶段时，我能给出的最好建议就是寻找兴奋感和热情，并毫无羞耻地去追求它，因为那种羞耻感标志着一个较低的心灵层级，而在那个追求的过程中，你可以培养出自信这种技能。</p><blockquote><p>有一些策略可以强行让你进入通道，我们称之为“故障（Glitches）”—— 就像母体（matrix）中的故障一样，如果母体是层级 1 和 2 的边界，直到你在层级 3 创造出你自己的边界。</p><p>迷幻药可以强行让人进入神秘体验。体能增强药物（PEDs）可以加速健身进度。搬进一个你负担不起的公寓可以提供一个真实的最后期限，迫使你不断学习和行动，直到你的副业起效。</p><p><strong>AI 是最新且最容易获得的跨越所有领域的故障。它可以被用来快速自我发展，也可以用来快速自我毁灭。</strong><em>品味和辨别力是必需的。</em>只有从狭隘的视角来看，AI 才是纯粹的善或纯粹的恶。</p><p>小心这些东西，因为虽然它们能加速进步，但风险极高。对于有特定目标的特定人群来说，它们是明智之举。但对于大多数人，尤其是处于层级 1 的人来说，它们就是死刑。</p><p>把你的“自然”潜力拉满，这样你才有充足的经验，不至于被一击秒杀（one-shotted）。知识和技能能降低风险。</p></blockquote><p>如果你感到迷茫，你大概处于失调阶段，如果你坚持下去，你就能找到你的下一条通道，并重新爱上生活。</p><h2 id="原型与元型" tabindex="-1">原型与元型 <a class="header-anchor" href="#原型与元型" aria-label="Permalink to &quot;原型与元型&quot;">​</a></h2><p><a href="https://substackcdn.com/image/fetch/$s_!0c-N!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F6b2a932a-1326-4a8a-85c3-e643b7840ce5_1277x1000.png" target="_blank" rel="noreferrer"><img src="'+n+'" alt=""></a></p><p>在未来的信件和视频中，我们可以使用人类3.0图谱（Human 3.0 Graph）来理解人（比如乔丹·彼得森（Jordan Peterson）、安德鲁·泰特（Andrew Tate）或艾伦·瓦茨（Alan Watts）），或者用来克服你生活中的问题，比如赚不到钱或找不到伴侣。</p><p>如果你对自己正面临的某个问题或想理解的某个人有具体的请求，请回复这封信。</p><p>在这个模型中，我加入了所谓的原型（Archetypes）和元型（Metatypes）。</p><ul><li><strong>原型（Archetypes）</strong> —— 在各象限及象限内不同层级中出现的人群模式。</li><li><strong>元型（Metatypes）</strong> —— 一个人在每个象限内四种原型的综合。</li></ul><p>可以把元型想象成一种人格测试，但是用于自我发展的。</p><p>我会在未来的信件中列出元型清单，并附上一个AI提示词，帮你找到自己的元型。</p><p>在上面的例子中，我在每个象限里只展示了3种原型。实际上远不止这些，所以请理解，这些设定并非固定不变的。我只是拿这些来玩一玩。</p><p>你会注意到，当一个人在某个象限内发展自己时，通常呈现出一种从低意识到高意识的递进过程：</p><p>在“心智（Mind）”象限中，<strong>NPC → 玩家（Player） → 创作者（Creator）</strong> 描述的是一个人不再按照出生时被赋予的剧本生活，开始玩自己的游戏，然后创造新的游戏去玩（类似于“构造层级”的觉知）。</p><p>在“身体（Body）”象限中，<strong>Incel（非自愿单身者） → Chad（猛男） → Sigma（西格玛男）</strong> 或 <strong>Beta男 → Alpha男 → Sigma男</strong>，是我们在当今世界常见的原型，可以通过一个人的行为和外表观察到。这可能与图谱上的其他领域相关联，或在同一象限内有更深层的原因。比如，一个Incel通常因饮食和环境因素而雌激素水平偏高，而“职业（Vocation）”象限中的社会结构导致了加工食品和微塑料的泛滥，这又在更大规模上加剧了这一问题。</p><p><strong>工作（Job） → 职业（Career） → 天命（Calling）</strong> 是“职业（Vocation）”象限中众多递进路径之一。就工作而言，如今这可以从任何事情开始。有些人甚至没有工作，或者早早就找到了自己的天命。关于每一层级递进的关键洞见是：它们都始于低意识（顺从者），并有能力递进到高意识（综合者）。</p><p>在“精神（Spirit）”象限中，<strong>宗教（Religion） → 无神论（Atheism） → 神秘主义（Mysticism）</strong> 是我们在那些成长于严格宗教家庭的人身上常见的一种模式（并非唯一模式），这会导致叛逆。随后，他们重新发现了对上帝的新视角，又绕回到第一层级中所包含的真理。</p><blockquote><p>肯·威尔伯（Ken Wilber）所说的“前理性/超理性谬误（pre-trans fallacy）”，发生在人们把前理性（顺从者）状态与超理性（综合者）状态混淆的时候，因为从常规的理性（个人主义者）视角来看，二者都显得“非理性”。这种混淆可以发生在两个方向上。</p><p>有人会把第一层级的原始状态抬升到第三层级的地位，也有人常常把真正的第三层级发展贬低为原始思维。</p><p>换句话说，一个缺乏知识和经验、只停留在童年信条中的“死抱圣经的人”，很难认真对待一位神秘主义者，尽管这位神秘主义者往往持有同样的真理，只是站在更全面的视角上。</p><p>如果有帮助的话，可以想想<a href="https://knowyourmeme.com/memes/iq-bell-curve-midwit" target="_blank" rel="noreferrer">IQ钟形曲线梗图</a>。</p></blockquote><p>当然，这只是发展性递进在“精神”象限中如何展开的一个次要例子。在人际关系、体育、家庭、科学或形而上学信仰等诸多领域中，都存在着各种各样的模式。</p><p><em>每个象限中都有数十到数百种原型，而不仅仅是我在每个象限展示的那三种。</em></p><p>现在，就上面给出的例子而言，当我们在每个象限、层级、阶段和特质中标出发展点时，我们就能全面地理解某个具体个体所处的位置。（你可以在图上那个半透明的白色形状中看到这一点。）</p><p>这个具体的人的例子会处于<strong>人类2.0（Human 2.0）</strong>。</p><p>我们是如何得出这一结论的？</p><p>每落在第一层级的一个点，得1分。</p><p>每落在第二层级的一个点，得2分。</p><p>每落在第三层级的一个点，得3分。</p><p>然后，我们把总分除以12（图谱上发展切片的总数），结果是2.0。</p><p>在这个例子中，我们可以为其在每个象限内的发展写出如下描述：</p><ul><li><strong>心智</strong> —— 不再按剧本生活，接近构造层级的觉知。</li><li><strong>身体</strong> —— 疏于打理，习惯不佳，但偶尔会展现出自信。</li><li><strong>精神</strong> —— 相信上帝的字面解释，但对无神论的朋友和同伴持宽容态度。</li><li><strong>职业</strong> —— 拥有一套有价值的教育背景和技能，但专注于一份安全且有满足感的职业。</li></ul><p>如果我们不只是为每个象限绘制3种原型，而是更多，这会变得更加复杂和全面，但我们把这个留给未来的信件。</p><p>现在，如果我们把这些描述整合成一个整体，就得到了他们的元型。我打算用AI来做这件事，因为我不想让它变成一个静态的“人格测试”，把你归到16个笼统的框框里的某一个。</p><p>在这个例子中，我们可以把这个人的元型视为“异类者（The Outlier）”。简而言之，这是一个已经偏离主流模式、却并非出于叛逆而漂移的人，他以一种反主流文化的视角运作。他们不在意自己的外表，但这可能是一种“虚假转变（False Transformation）”，因为他们在“身体”象限缺乏经验。</p><p>这仅仅是人类3.0模型的基础，我们还有更多细微之处需要展开。</p><p>—— 丹（Dan）</p><hr><p><a href="/en/letters/human-3-0-a-map-to-reach-the-top-1">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',107))])}const x=l(d,[["render",b]]);export{T as __pageData,x as default};
